import {worldChart} from './chart.mjs';
const $=s=>document.querySelector(s),page=document.body.dataset.page;
const labels={economy:'經濟',environment:'環境',society:'社會'},phases={setup:'準備中',live:'交易進行中',paused:'已暫停',reflection:'反思階段',archived:'已封存'};
let token=sessionStorage.getItem(page+'Token')||'',cards=[],latest=null,pending=null,busy=false,refreshing=false,selectedActivity=page==='admin'?(new URLSearchParams(location.search).get('activity')||''):'',activityList=[],formActivity='',confirmActivity='',confirmedTrade=null;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function uid(){return globalThis.crypto?.randomUUID?.()||'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=Math.random()*16|0;return(c==='x'?r:(r&3|8)).toString(16)})}
async function api(path,body){const response=await fetch('/api/'+path,{method:body?'POST':'GET',headers:{'content-type':'application/json',authorization:'Bearer '+token},body:body?JSON.stringify({...body,activityId:body.activityId??latest?.activity?.id}):undefined,signal:AbortSignal.timeout(12000)});const data=await response.json();if(!response.ok){const e=Error(data.error||'連線失敗');e.rejected=data.rejected===true;throw e;}return data}
function notice(msg,error=false){$('#notice').textContent=msg;$('#notice').className=error?'error':'success'}
function chart(history){$('#chart').innerHTML=worldChart(history)}
function world(s){$('#phase').textContent=phases[s.phase];for(const k of Object.keys(labels))$('#'+k).textContent=s.state[k];chart(s.history);$('#total').textContent=s.total;const events=$('#events');if(events){events.innerHTML=(s.phase==='reflection'||s.phase==='archived')?'<h2>回顧世界的轉折</h2><p class="muted">依實際變化篩選：歸零、從零回升、單筆變化至少 2。這是討論線索，不是因果結論；未自動判斷卡片執行門檻。</p>'+((s.events||[]).map(e=>`<div class="event"><strong>第 ${e.step} 筆 · ${esc(e.group)} 組 · #${e.cardId} ${esc(e.name)}</strong><p>${e.reasons.map(r=>esc(r.replace(/economy|environment|society/g,k=>labels[k]))).join(' ／ ')}</p><span>${Object.keys(labels).map(k=>`${labels[k]} ${e.before[k]} → ${e.after[k]}`).join('　')}</span></div>`).join('')||'<p>目前沒有符合條件的事件。</p>'):''}}
async function refresh(){if(refreshing)return;refreshing=true;try{const requestedActivity=selectedActivity;const s=await api(page==='admin'?'admin/state'+(selectedActivity?'?activity='+encodeURIComponent(selectedActivity):''):'state');if(page==='admin'&&requestedActivity!==selectedActivity)return;const changed=latest?.activity?.id&&latest.activity.id!==s.activity.id;latest=s;$('#activityLabel').textContent=s.activity.date+' ｜ '+s.activity.name+(s.activity.archived?'（已封存）':'');if(page==='exchange'&&(changed||!cards.length)){cards=await api('cards');$('#confirmDialog').close();$('#cardId').value='';notice('活動已切換，請確認活動名稱與組別');}$('#connection').textContent='● 已同步 · '+new Date().toLocaleTimeString('zh-TW');$('#connection').className='success';if(page==='dashboard'||page==='admin')world(s);if(page==='exchange'){$('#phase').textContent=phases[s.phase];const old=$('#group').value;$('#group').innerHTML=s.groups.map(g=>`<option value="${esc(g)}">${esc(g)} 組</option>`).join('');$('#group').value=s.groups.includes(old)?old:(s.groups.includes('H')?'H':s.groups[0]);$('#review').disabled=s.phase!=='live'||!cards.length||!!pending;$('#availability').textContent=pending?'上一筆結果尚未確認，請按重試上一筆交易。':s.phase!=='live'?'目前為「'+phases[s.phase]+'」，無法送出交易。請引導師在後台按「開放交易」。':!cards.length?'專案卡尚未載入，請重新整理或聯絡引導師。':'交易已開放：請選組別、輸入卡號，再確認專案。';$('#count').textContent=s.total;}
if(page==='admin'){if(activityList.length){const item=activityList.find(a=>a.id===s.activity.id);if(item)item.total=s.total;$('#activitySummary').textContent=`累積 ${activityList.length} 場 · 有效交易 ${activityList.reduce((n,a)=>n+a.total,0)} 次`;}renderActivities(s);$('#cardCount').textContent=s.cardCount;$('#counts').innerHTML=s.groups.map(g=>`<span class="stat">${esc(g)} 組 <b>${s.counts[g]||0}</b> 次</span>`).join('');$('#rows').innerHTML=[...s.trades].reverse().map(t=>`<tr class="${t.voided?'void':''}"><td>${t.id}</td><td>${esc(t.group_name)}</td><td>#${t.card_id} ${esc(t.name)}</td><td>${t.economy} / ${t.environment} / ${t.society}</td><td>${new Date(t.created_at).toLocaleTimeString('zh-TW')}</td><td>${t.voided?esc(t.void_reason):(s.activity.archived||s.activity.id!==s.activeId)?'封存紀錄':`<button class="secondary" data-void="${t.id}">撤銷</button>`}</td></tr>`).join('');}
}catch(e){$('#connection').textContent='● 同步中斷 · '+e.message+'；目前顯示最後成功資料';$('#connection').className='error'}finally{refreshing=false}}
async function login(){token=$('#password').value||token;try{await api(page==='admin'?'admin/state':'cards');sessionStorage.setItem(page+'Token',token);$('#login').hidden=true;$('#workspace').hidden=false;if(page==='exchange'){cards=await api('cards');const p=sessionStorage.getItem('pendingTrade');if(p){pending=JSON.parse(p);$('#retry').hidden=false;notice('有一筆尚未確認結果的交易，請按「重試上一筆交易」。')}}await refresh()}catch(e){notice(e.message,true)}}
