(async()=>{try{cards=await api('cards');const p=sessionStorage.getItem('pendingTrade');if(p){pending=JSON.parse(p);$('#retry').hidden=false;notice('有一筆尚未確認結果的交易，請按「重試上一筆交易」。')}await refresh()}catch(e){notice(e.message+'，請重新整理頁面。',true)}})();
$('#group').onchange=()=>refresh();$('#review').onclick=()=>{if(busy||pending||latest?.phase!=='live')return;confirmActivity=latest.activity.id;const card=cards.find(c=>c.id===Number($('#cardId').value));if(!card)return notice('請輸入有效卡號 1–80',true);confirmedTrade={activityId:confirmActivity,group:$('#group').value,cardId:card.id};$('#confirmation').textContent=`${$('#group').value} 組｜#${card.id} ${card.name}`;$('#confirmDialog').showModal()};
$('#cancel').onclick=()=>$('#confirmDialog').close();$('#confirm').onclick=()=>{if(busy||pending||!confirmedTrade)return;pending={...confirmedTrade,requestId:uid()};sessionStorage.setItem('pendingTrade',JSON.stringify(pending));$('#confirmDialog').close();submit()};$('#retry').onclick=submit;
