export function chartScale(history){const count=Math.max(0,history.length-1);return {count,xMax:Math.max(80,Math.ceil(count/80)*80),yMax:Math.max(20,Math.ceil(Math.max(0,...history.flatMap(s=>[s.economy,s.environment,s.society]))/20)*20)}}
export function worldChart(history){const {count,xMax,yMax}=chartScale(history),w=960,h=360,left=48,right=26,top=32,bottom=52,x=i=>left+i/xMax*(w-left-right),y=v=>h-bottom-v/yMax*(h-top-bottom);let svg=`<title>世界狀態趨勢：目前${count}筆，橫軸0至${xMax}筆有效交易</title>`;
for(let i=0;i<=4;i++){const v=yMax*i/4;svg+=`<line x1="${left}" y1="${y(v)}" x2="${w-right}" y2="${y(v)}" stroke="#dce5dc"/><text x="${left-10}" y="${y(v)+5}" text-anchor="end" fill="#52685d" font-size="13">${v}</text>`}
for(let i=0;i<=8;i++){const v=xMax*i/8;svg+=`<line x1="${x(v)}" y1="${top}" x2="${x(v)}" y2="${h-bottom}" stroke="#edf1eb"/><text x="${x(v)}" y="${h-bottom+23}" text-anchor="middle" fill="#52685d" font-size="13">${v}</text>`}
svg+=`<text x="${left}" y="18" fill="#52685d" font-size="13">世界狀態數值</text><text x="${w-right}" y="${h-7}" text-anchor="end" fill="#52685d" font-size="13">有效交易次數</text><line x1="${x(count)}" y1="${top}" x2="${x(count)}" y2="${h-bottom}" stroke="#81958a" stroke-dasharray="4 4"/><text x="${Math.min(w-right-100,x(count)+8)}" y="18" fill="#244c3e" font-size="13">目前 ${count} 筆</text>`;
[['economy','經濟','#197cd2',''],['environment','環境','#168458','8 3'],['society','社會','#c6920b','3 3']].forEach(([key,name,color,dash])=>{svg+=`<polyline fill="none" stroke="${color}" stroke-width="3" stroke-dasharray="${dash}" points="${history.map((s,i)=>`${x(i)},${y(s[key])}`).join(' ')}"/>`;history.forEach((s,i)=>{svg+=`<circle cx="${x(i)}" cy="${y(s[key])}" r="3" fill="${color}" stroke="white" stroke-width=".7"><title>第${i}筆・${name} ${s[key]}</title></circle>`})});return svg}

