function render(){const pages=Math.max(1,Math.ceil(filtered.length/10));page=Math.min(page,pages);$('#historySummary').textContent=`找到 ${filtered.length} 場已封存活動`;$('#historyResults').innerHTML=filtered.slice((page-1)*10,page*10).map(a=>`<article class="card"><h2>${esc(a.name)}</h2><p>${esc(a.event_date)} · 已封存 · 有效交易 ${a.total} 次</p><a class="button" href="/admin?activity=${encodeURIComponent(a.id)}">查看場次詳情 →</a></article>`).join('')||'<p>沒有符合條件的封存活動。尚未封存的場次請至目前活動查看。</p>';$('#pageNumber').textContent=`第 ${page}／${pages} 頁`;$('#previousPage').disabled=page===1;$('#nextPage').disabled=page===pages;}
function filter(){const name=$('#searchName').value.trim().toLocaleLowerCase(),from=$('#dateFrom').value,to=$('#dateTo').value;if(from&&to&&from>to){$('#historyMessage').textContent='起始日期不能晚於結束日期';return}$('#historyMessage').textContent='';filtered=rows.filter(a=>(!name||a.name.toLocaleLowerCase().includes(name))&&(!from||a.event_date>=from)&&(!to||a.event_date<=to));page=1;render()}
