import {handleActions} from './actions.mjs';
import {replay,validateCards} from './domain.mjs';
const json=(v,status=200)=>new Response(JSON.stringify(v),{status,headers:{'content-type':'application/json; charset=utf-8','cache-control':'no-store'}});
const groupsOK=g=>Array.isArray(g)&&g.length>0&&g.length<=60&&new Set(g).size===g.length&&g.every(x=>typeof x==='string'&&x.trim()===x&&x.length>0&&x.length<=20);
const metaOK=b=>typeof b.name==='string'&&b.name.trim().length>0&&b.name.length<=120&&typeof b.date==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(b.date)&&!isNaN(Date.parse(b.date))&&new Date(b.date).toISOString().slice(0,10)===b.date;
export async function handle(request,env){if(new URL(request.url).pathname.startsWith('/api/actions/'))return handleActions(request,env);try{
 const url=new URL(request.url),path=url.pathname.replace('/api/',''),db=env.DB;
 if(!db)return json({error:'資料庫尚未設定'},503);
 const token=request.headers.get('authorization')?.replace(/^Bearer /,''),admin=!!env.ADMIN_TOKEN&&token===env.ADMIN_TOKEN,operator=admin||(!!env.OPERATOR_TOKEN&&token===env.OPERATOR_TOKEN);
 if(!['state','cards','counts','trade'].includes(path)&&!operator)return json({error:'請輸入正確的工作人員密碼'},401);
 if(path.startsWith('admin/')&&!admin)return json({error:'需要引導師密碼'},403);
 if(request.method==='POST'&&request.headers.get('origin')&&request.headers.get('origin')!==url.origin)return json({error:'來源不符'},403);
 const settings=await db.prepare('SELECT * FROM settings WHERE id=1').first(),active=settings.active_activity;
 const id=admin&&path==='admin/state'&&url.searchParams.get('activity')?url.searchParams.get('activity'):active;
 const a=await db.prepare('SELECT * FROM activities WHERE id=?').bind(id).first();
 if(!a)return json({error:'活動不存在'},404);
 const rows=async aid=>(await db.prepare('SELECT * FROM trades WHERE activity_id=? ORDER BY id').bind(aid).all()).results;
 if(request.method==='GET'){
  if(path==='admin/activities')return json({activeId:active,activities:(await db.prepare('SELECT a.*, (SELECT count(*) FROM trades t WHERE t.activity_id=a.id AND t.voided=0) total FROM activities a ORDER BY event_date DESC,created_at DESC,id').all()).results});
  if(path==='state'||path==='admin/state'){
   const ts=await rows(id),r=replay(ts),result={activity:{id:a.id,name:a.name,date:a.event_date,archived:!!a.archived},activeId:active,phase:a.archived?'archived':a.phase,groups:JSON.parse(a.groups_json),state:r.state,history:r.history,total:r.total};
   if(admin&&path==='admin/state'){result.trades=ts;result.counts=r.counts;result.cardCount=(await db.prepare('SELECT count(*) n FROM activity_cards WHERE activity_id=?').bind(id).first()).n;result.cardSnapshot=(await db.prepare('SELECT id,name,economy,environment,society FROM activity_cards WHERE activity_id=? ORDER BY id').bind(id).all()).results;}
   if(a.phase==='reflection'||a.archived)result.events=r.events;return json(result);
  }
  if(path==='cards')return json((await db.prepare('SELECT id,name FROM activity_cards WHERE activity_id=? ORDER BY id').bind(active).all()).results);
  if(path==='counts')return json(replay(await rows(active)).counts);
 }
 if(request.method!=='POST')return json({error:'找不到此功能'},404);
 const body=await request.json();
 if(path==='admin/create'){
  if(!metaOK(body)||!groupsOK(body.groups)||!/^[-a-zA-Z0-9]{16,80}$/.test(body.id||''))return json({error:'請填寫有效活動名稱、日期與組別'},400);
  const existing=await db.prepare('SELECT id FROM activities WHERE id=?').bind(body.id).first();if(existing)return json({ok:true,id:existing.id,duplicate:true});
  // The batch atomically checks the expected current activity, snapshots cards and advances the pointer.
  const guard="(SELECT active_activity FROM settings WHERE id=1)=? AND EXISTS(SELECT 1 FROM activities WHERE id=? AND archived=1)";
  const out=await db.batch([
   db.prepare(`INSERT INTO activities(id,name,event_date,groups_json) SELECT ?,?,?,? WHERE ${guard}`).bind(body.id,body.name.trim(),body.date,JSON.stringify(body.groups),body.activityId||'',body.activityId||''),
   db.prepare('INSERT INTO activity_cards SELECT ?,id,name,economy,environment,society FROM activity_cards WHERE activity_id=? AND EXISTS(SELECT 1 FROM activities WHERE id=?)').bind(body.id,active,body.id),
   db.prepare('UPDATE settings SET active_activity=? WHERE id=1 AND active_activity=? AND EXISTS(SELECT 1 FROM activities WHERE id=?)').bind(body.id,active,body.id)
  ]);
  return out[0].meta.changes?json({ok:true,id:body.id}):json({error:'請先封存目前活動，再建立下一場；若已切換請重新整理'},409);
 }
 if(path==='trade'){
  if(!/^[-a-zA-Z0-9]{16,80}$/.test(body.requestId||''))return json({error:'交易識別碼不正確'},400);
  const old=await db.prepare('SELECT * FROM trades WHERE request_id=?').bind(body.requestId).first();
  if(old){if(old.activity_id!==body.activityId||old.group_name!==body.group||old.card_id!==Number(body.cardId))return json({error:'交易識別碼已使用'},409);return json({ok:true,id:old.id,duplicate:true,voided:!!old.voided});}
 }
 if(body.activityId!==active)return json({error:'活動已切換或頁面版本過舊，請重新整理後確認活動名稱',rejected:true},409);
 const editable="id=? AND archived=0 AND id=(SELECT active_activity FROM settings WHERE id=1)";
 const allowed="EXISTS(SELECT 1 FROM activities WHERE id=? AND archived=0 AND id=(SELECT active_activity FROM settings WHERE id=1))";
 if(path==='trade'){
  if(!JSON.parse(a.groups_json).includes(body.group))return json({error:'組別不存在',rejected:true},400);
  await db.prepare(`INSERT OR IGNORE INTO trades(activity_id,request_id,group_name,card_id,name,economy,environment,society) SELECT activity_id,?,?,id,name,economy,environment,society FROM activity_cards WHERE activity_id=? AND id=? AND EXISTS(SELECT 1 FROM activities WHERE ${editable} AND phase='live' AND EXISTS(SELECT 1 FROM json_each(groups_json) WHERE value=?))`).bind(body.requestId,body.group,active,Number(body.cardId),active,body.group).run();
  const saved=await db.prepare('SELECT id FROM trades WHERE request_id=? AND activity_id=?').bind(body.requestId,active).first();return saved?json({ok:true,id:saved.id}):json({error:'尚未開放交易、已封存，或卡號無效',rejected:true},409);
 }
 if(path==='admin/phase'){
  if(!['setup','live','paused','reflection'].includes(body.phase))return json({error:'階段無效'},400);
  const r=await db.prepare(`UPDATE activities SET phase=? WHERE ${editable} AND (?!='live' OR (SELECT count(*) FROM activity_cards WHERE activity_id=activities.id)=80)`).bind(body.phase,active,body.phase).run();return r.meta.changes?json({ok:true}):json({error:'活動已封存或尚未匯入80張卡'},409);
 }
 if(path==='admin/archive'){
  const r=await db.prepare(`UPDATE activities SET archived=1,phase='reflection',archived_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE ${editable} AND phase!='live'`).bind(active).run();return r.meta.changes?json({ok:true}):json({error:'請先暫停或進入反思；活動可能已封存'},409);
 }
 if(path==='admin/metadata'){
  if(!metaOK(body))return json({error:'請填寫有效活動名稱與日期'},400);
  const r=await db.prepare(`UPDATE activities SET name=?,event_date=? WHERE ${editable}`).bind(body.name.trim(),body.date,active).run();return r.meta.changes?json({ok:true}):json({error:'封存活動僅供回顧'},409);
 }
 if(path==='admin/void'){
  if(!Number.isInteger(body.id)||typeof body.reason!=='string'||!body.reason.trim()||body.reason.length>200)return json({error:'請填寫交易編號與撤銷原因'},400);
  const r=await db.prepare(`UPDATE trades SET voided=1,void_reason=?,voided_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id=? AND activity_id=? AND voided=0 AND EXISTS(SELECT 1 FROM activities WHERE ${editable} AND phase!='live')`).bind(body.reason,body.id,active,active).run();return r.meta.changes?json({ok:true}):json({error:'請先暫停；已封存、已撤銷或其他場次紀錄不能修改'},409);
 }
 if(path==='admin/groups'){
  if(!groupsOK(body.groups))return json({error:'請填寫1–60個不重複組別'},400);
  const r=await db.prepare(`UPDATE activities SET groups_json=? WHERE ${editable} AND phase='setup' AND NOT EXISTS(SELECT 1 FROM trades WHERE activity_id=activities.id)`).bind(JSON.stringify(body.groups),active).run();return r.meta.changes?json({ok:true}):json({error:'僅可於準備階段且尚無交易時修改組別'},409);
 }
 if(path==='admin/import'){
  validateCards(body.cards);const guard=`${allowed} AND EXISTS(SELECT 1 FROM activities WHERE id=? AND phase='setup') AND NOT EXISTS(SELECT 1 FROM trades WHERE activity_id=?)`;
  const results=await db.batch([db.prepare(`DELETE FROM activity_cards WHERE activity_id=? AND ${guard}`).bind(active,active,active,active),...body.cards.map(c=>db.prepare(`INSERT OR REPLACE INTO activity_cards SELECT ?,?,?,?,?,? WHERE ${guard}`).bind(active,c.id,c.name,c.economy,c.environment,c.society,active,active,active))]);return results[1].meta.changes?json({ok:true,count:80}):json({error:'僅可於準備階段且尚無交易時匯入'},409);
 }
 return json({error:'找不到此功能'},404);
}catch(e){console.error('API failure',e.message);return json({error:'處理失敗，請檢查輸入或稍後重試'},400);}}

